xpath.script:

function subst() {
    var vars = {};
    var x = document.location.search.substring(1).split('&');
    for (var i in x) {
        var z = x[i].split('=', 2);
        vars[z[0]] = decodeURIComponent(z[1] || '');
    }

    var keys = ['sitepage', 'sitepages', 'section', 'subsection', 'subsubsection'];
    var map = {'sitepage': 'page', 'sitepages': 'topage'};

    for (var i in keys) {
        var y = document.getElementsByClassName(map[keys[i]] || keys[i]);
        for (var j = 0; j < y.length; ++j) {
            y[j].textContent = vars[keys[i]] || '';
        }
    }

    var index = vars['webpage'] ? vars['webpage'].split('.', 4)[3] : 0;

    var header = document.getElementById('minimal_layout_report_headers');
    if (header && header.children[index]) {
        var companyHeader = header.children[index];
        header.textContent = '';
        header.appendChild(companyHeader);
    }

    var footer = document.getElementById('minimal_layout_report_footers');
    if (footer && footer.children[index]) {
        var companyFooter = footer.children[index];
        footer.textContent = '';
        footer.appendChild(companyFooter);
    }

    var operations = {
        'not-first-page': function (elt) {
            elt.style.display = (vars.sitepage === vars.frompage) ? 'none' : 'inherit';
        },
        'not-last-page': function (elt) {
            elt.style.display = (vars.sitepage === vars.sitepages) ? 'none' : 'inherit';
        },
        'first-page': function (elt) {
            elt.style.display = (vars.sitepage === vars.frompage) ? 'inherit' : 'none';
        },
        'last-page': function (elt) {
            elt.style.display = (vars.sitepage === vars.sitepages) ? 'inherit' : 'none';
        },
        'single-page': function (elt) {
            elt.style.display = (vars.sitepages === '1') ? 'inherit' : 'none';
        },
        'multi-page': function (elt) {
            elt.style.display = (vars.sitepages > 1) ? 'inherit' : 'none';
        }
    };

    for (var klass in operations) {
        var elts = document.getElementsByClassName(klass);
        for (var j = 0; j < elts.length; ++j) {
            operations[klass](elts[j]);
        }
    }
}
